# apply_app_patch.ps1
# ---------------------------------------------------------------------------
# NOTE: This script is intentionally ASCII-only. Windows PowerShell 5.1 reads
#       .ps1 files as ANSI unless they carry a UTF-8 BOM, so non-ASCII text
#       inside a BOM-less UTF-8 script gets mangled and breaks parsing.
#
# Purpose: wire the hand-written code in firmware-stm32/App into the Makefile
#          generated by STM32CubeMX, and repair one CubeMX defect.
#          CubeMX REBUILDS cubemx/Projects/Makefile on every "GENERATE CODE",
#          so run this script once after each regeneration. It is idempotent.
#
# Usage (Windows blocks unsigned .ps1 by default, hence -ExecutionPolicy Bypass):
#   powershell -ExecutionPolicy Bypass -NoProfile -File apply_app_patch.ps1
#
# What it does:
#   0) Removes C_SOURCES entries whose file does not exist.
#      Measured: CubeMX 6.17 lists ../Src/sysmem.c and ../Src/syscalls.c in
#      C_SOURCES but never generates them, so make stops with
#      "No rule to make target 'build/sysmem.o'".
#      Only lines whose file is really missing are dropped.
#   1) Appends the 5 ../../App/<sub>/*.c files to C_SOURCES.
#      IMPORTANT: must go *inside* the C_SOURCES definition, because
#      "vpath %.c $(sort $(dir $(C_SOURCES)))" is expanded at parse time.
#      Appending at end of file would leave the App dir out of vpath and make
#      would fail with "No rule to make target 'xxx.c'".
#   2) Adds -I../../App to C_INCLUDES.
#   3) Adds -DREGBANK_USE_FREERTOS to C_DEFS.
#      Do NOT drop this one: regbank.h uses it to select
#      taskENTER_CRITICAL() for its critical sections. Without it the
#      critical sections silently become no-ops (compiles fine, but the
#      register bank can be torn between tasks).
param(
    [string]$Makefile = (Join-Path $PSScriptRoot 'cubemx\Projects\Makefile')
)

$ErrorActionPreference = 'Stop'

function Write-Info ([string]$m) { Write-Host "  $m" }
function Write-Ok   ([string]$m) { Write-Host "  [OK]   $m" -ForegroundColor Green }
function Write-Skip ([string]$m) { Write-Host "  [SKIP] $m" -ForegroundColor DarkGray }

Write-Host "== apply_app_patch ==" -ForegroundColor Cyan
Write-Info "target: $Makefile"

if (-not (Test-Path -LiteralPath $Makefile)) {
    Write-Host "Makefile not found. Run GENERATE CODE in CubeMX first (project should land in cubemx\Projects)." -ForegroundColor Red
    exit 1
}

$raw     = [System.IO.File]::ReadAllText($Makefile)
$newline = if ($raw -match "`r`n") { "`r`n" } else { "`n" }
$lines   = [System.IO.File]::ReadAllLines($Makefile)
$projDir = Split-Path -Parent $Makefile
$changed = $false

# ---- 0) drop C_SOURCES entries that point at files that do not exist -------
$removed = New-Object System.Collections.Generic.List[string]
$kept    = New-Object System.Collections.Generic.List[string]
foreach ($l in $lines) {
    $entry = ($l -replace '\s*\\\s*$', '').Trim()
    if (($entry -like '../Src/*') -or ($entry -like '../../App/*')) {
        $full = [System.IO.Path]::GetFullPath((Join-Path $projDir $entry))
        if (-not (Test-Path -LiteralPath $full)) {
            $removed.Add($entry)
            continue
        }
    }
    $kept.Add($l)
}
if ($removed.Count -gt 0) {
    $lines   = $kept.ToArray()
    $changed = $true
    Write-Ok ("dropped missing source(s): " + ($removed -join ', '))
} else {
    Write-Skip 'no missing source files in C_SOURCES'
}

$text = $lines -join "`n"

# ---- 1) C_SOURCES: insert the 4 App sources --------------------------------
if ($text -match [regex]::Escape('../../App/app/app_main.c')) {
    Write-Skip 'C_SOURCES already contains the App sources'
} else {
    $idx = -1
    foreach ($anchor in @('../Src/syscalls.c',
                          '../Middlewares/Third_Party/FreeRTOS/Source/portable/GCC/ARM_CM4F/port.c')) {
        for ($i = 0; $i -lt $lines.Count; $i++) {
            if ((($lines[$i] -replace '\s*\\\s*$', '').Trim()) -eq $anchor) { $idx = $i; break }
        }
        if ($idx -ge 0) { break }
    }
    if ($idx -lt 0) {
        Write-Host "No usable anchor found in C_SOURCES - Makefile layout changed. Add the 5 ../../App/<sub>/*.c lines by hand." -ForegroundColor Red
        exit 1
    }
    $insert = @(
        '../../App/protocol/modbus_crc.c \',
        '../../App/protocol/modbus_slave.c \',
        '../../App/regmap/regbank.c \',
        '../../App/features/vibration_feat.c \',
        '../../App/app/app_main.c'
    )
    $lines[$idx] = ($lines[$idx] -replace '\s*\\\s*$', '') + ' \'
    $head = if ($idx -gt 0) { $lines[0..$idx] } else { @($lines[0]) }
    $tail = if ($idx + 1 -lt $lines.Count) { $lines[($idx + 1)..($lines.Count - 1)] } else { @() }
    $lines   = @($head) + $insert + @($tail)
    $changed = $true
    Write-Ok 'C_SOURCES: added the 5 App source files'
}

# ---- 2) C_INCLUDES --------------------------------------------------------
$text = $lines -join "`n"
if ($text -match [regex]::Escape('-I../../App/app')) {
    Write-Skip 'C_INCLUDES already has the App sub-dir includes'
} else {
    $lines += ''
    $lines += '# ---- hand-written app code (firmware-stm32/App): appended by apply_app_patch.ps1 ----'
    $lines += 'C_INCLUDES += -I../../App/protocol -I../../App/regmap -I../../App/features -I../../App/app'
    $changed = $true
    Write-Ok 'C_INCLUDES: added 4 App sub-dir includes'
}

# ---- 3) C_DEFS ------------------------------------------------------------
$text = $lines -join "`n"
if ($text -match [regex]::Escape('-DREGBANK_USE_FREERTOS')) {
    Write-Skip 'C_DEFS already has -DREGBANK_USE_FREERTOS'
} else {
    $lines += 'C_DEFS += -DREGBANK_USE_FREERTOS'
    $changed = $true
    Write-Ok 'C_DEFS: added -DREGBANK_USE_FREERTOS'
}

if ($changed) {
    [System.IO.File]::WriteAllText($Makefile, (($lines -join $newline) + $newline),
                                   (New-Object System.Text.UTF8Encoding($false)))
    Write-Host "Makefile written. Next: make -C cubemx/Projects -j8" -ForegroundColor Cyan
} else {
    Write-Host "Nothing to do (already up to date)." -ForegroundColor Cyan
}
exit 0
